// The Slack alert when the invoice workflow itself fails: credentials expired,
// Google Sheets or Slack down. Invoices that can't be read don't land here;
// they go to the Review tab.
const { execution = {}, workflow = {} } = $json;

const escape = (value) =>
  String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const lines = [
  `:rotating_light: *${escape(workflow.name || 'Invoice processing')} failed*`,
  `Step: ${escape(execution.lastNodeExecuted || 'unknown')}`,
  `> ${escape(execution.error?.message || 'No error message')}`,
  execution.url
    ? `<${execution.url}|Open the execution>, fix the cause, then retry it from n8n.`
    : 'Open n8n → Executions, fix the cause, then retry the execution.',
];

return { json: { text: lines.join('\n') } };
